   345
   346    // Allocate above context buffers
   347    above_contexts->num_tile_rows = num_tile_rows;
   348    above_contexts->num_mi_cols = aligned_mi_cols;
   349    above_contexts->num_planes = num_planes;
   350    for (int plane_idx = 0; plane_idx < num_planes; plane_idx++) {
   351      above_contexts->entropy[plane_idx] = (ENTROPY_CONTEXT **)aom_calloc(
   352          num_tile_rows, sizeof(above_contexts->entropy[0]));
   353      if (!above_contexts->entropy[plane_idx]) return 1;
   354    }
   355
   356    above_contexts->partition = (PARTITION_CONTEXT **)aom_calloc(
   357        num_tile_rows, sizeof(above_contexts->partition));
