   376      above_contexts->txfm[tile_row] = (TXFM_CONTEXT *)aom_calloc(
   377          aligned_mi_cols, sizeof(*above_contexts->txfm[tile_row]));
   378      if (!above_contexts->txfm[tile_row]) return 1;
