    62    assert(bsize < BLOCK_SIZES_ALL);
    63    const int nplanes = 1 + (num_planes - 1) * xd->is_chroma_ref;
    64    for (int i = 0; i < nplanes; i++) {
    65      struct macroblockd_plane *const pd = &xd->plane[i];
